let rrIndex=null;
function rrBytes(encoded) {return Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));}
function rrEncode(question,index) {
 const f=rrParse(question),dense=new Float32Array(index.dims);
 const sparse=new Map();let ss=0;
 for(const [j,count] of f.vector){
  const w=Math.log1p(count)*index.idf[j];sparse.set(j,w);ss+=w*w;
  for(let k=0;k<dense.length;k++)dense[k]+=w*index.projection[k*2048+j];
 }
 const norm=Math.sqrt(ss)||1,dn=Math.hypot(...dense)||1;
 for(const [j,w] of sparse)sparse.set(j,w/norm);
 for(let k=0;k<dense.length;k++)dense[k]/=dn;
 return {...f,sparse,dense};
}
function rrSignature(s){
 let lo=2166136261,hi=5381;
 for(let i=0;i<s.length;i++){lo=Math.imul(lo^s.charCodeAt(i),16777619);hi=Math.imul(hi,33)^s.charCodeAt(i);}
 return (lo>>>0).toString(36)+'/'+(hi>>>0).toString(36);
}
function rrDatabase(){
 if(rrIndex)return rrIndex;
 const index={dims:rrModel.dims,idf:new Float32Array(rrBytes(rrModel.idf).buffer),projection:new Int8Array(rrBytes(rrModel.components).buffer)};
 const vectors=new Float32Array(rrBytes(rrModel.vectors).buffer);
 index.docs=rrModel.entries.map(([count,expr,signature],i)=>({id:i+1,count,expr,signature,dense:vectors.subarray(i*index.dims,(i+1)*index.dims)}));
 rrIndex=index;return index;
}
function rrNeighbors(question,mode='hybrid'){
 const index=rrDatabase(),query=rrEncode(question,index);
 if(query.nums.length<2||query.nums.length>4||new Set(query.nums).size!==query.nums.length)return null;
 const ranked=[],signature=rrSignature(query.signature);
 for(const doc of index.docs){
  if(doc.count!==query.nums.length||doc.signature===signature)continue;
  let dense=0;
  for(let k=0;k<query.dense.length;k++)dense+=query.dense[k]*doc.dense[k];
  const score=dense;
  ranked.push({id:doc.id,expr:doc.expr,score,dense});
 }
 ranked.sort((a,b)=>b.score-a.score);
 return {top:ranked.slice(0,5),nums:query.nums};
}
function rrVote(hit){
 if(!hit?.top.length)return null;
 const tally=new Map();let total=0;
 for(const n of hit.top){const w=Math.exp(14*(n.score-hit.top[0].score));total+=w;tally.set(n.expr,(tally.get(n.expr)||0)+w);}
 const [expr,w]=[...tally].sort((a,b)=>b[1]-a[1])[0];
 return {expr,share:w/total,count:hit.top.filter(n=>n.expr===expr).length};
}
function retrieveProgram(question,base,solve){
 if(/\b(percent|perimeter|interest|area|discount|profit|ratio|remainder|least common|greatest common|more .* needed|at least|minimum|maximum)\b|%/i.test(question))return null;
 const hit=rrNeighbors(question,rrConfig.mode),vote=rrVote(hit);
 if(!vote||hit.top[0].score<rrConfig.peak||vote.share<rrConfig.share||vote.count<2||vote.expr!==hit.top[0].expr)return null;
 const unitMatch=question.toLowerCase().match(/\bhow many\s+([a-z]+)\b/g)?.at(-1);
 const noun=unitMatch?.split(' ').at(-1);
 const count=noun&&!['more','fewer','of','times','other','additional','different','extra','equal','new','whole','complete','total'].includes(noun)?noun:null;
 const money=/how much (money|did .* (pay|spend))/i.test(question);
 if(!count&&!money)return null;
 const text='(problem (kind num.ops) (evaluate '+vote.expr.replace(/\$(\d+)/g,(_,i)=>String(hit.nums[+i]))+'))';
 const r=solve(text,{question});if(!r?.ok||r.warnings?.length||r.answers?.length!==1||r.fit?.level==='strong')return null;
 const a=r.answers[0],value=Number(a.value);
 if(!Number.isFinite(value)||value<0||(count&&!Number.isInteger(value)))return null;
 const unit=count||(/\$|\bdollars?\b/i.test(question)?'dollars':null);
 if(!unit)return null;
 const reader=base?.r?.answers;
 const supported=reader?.length===1&&Math.abs(Number(reader[0].value)-value)<1e-8;
 const corroboration=supported?'reader-agrees':!reader?.length?'reader-abstained':'reader-disagrees';
 if(rrConfig.gate==='agree'&&!supported)return null;
 if(rrConfig.gate==='abstain'&&reader?.length)return null;
 if(rrConfig.gate==='agree-or-abstain'&&reader?.length&&!supported)return null;
 if(rrConfig.gate==='grounded'&&!supported){
  const op=vote.expr.slice(1,2);
  const relational=op==='*'&&/\beach (?:[a-z]+ )?(?:held|holds|has|had|contains|contained)|\b(?:in|on) each\b/.test(question.toLowerCase()) ||
    op==='+'&&/all together|altogether|(?:have|make|give|sell) in total/i.test(question) ||
    op==='-'&&/how many .{0,30}(?:are left|remain|still have)/i.test(question);
  if(!relational)return null;
 }
 const neighbors=hit.top.map(n=>({id:n.id,template:n.expr,score:+n.score.toFixed(3),dense:+n.dense.toFixed(3)}));
 return {text,r:{...r,answers:[{...a,unit,text:a.value+' '+unit}]},source:'retrieval',retrieval:{corroboration,template:vote.expr,share:vote.share,neighbors}};
}

